const SKETCH_TITLE = "Galaxy Collision"

var cellList = []
var attractorList = []
var nC = 1000;
var nA = 10;
var trails = 20;
var aMassSlider,gSizeSlider,nCSlider,sACheckbox;
var palette;
var paletteIdx; 
var bg;
var xSpacing, ySpacing;
var dynamic_attractors = true;

// useful test to determine if code is running on a mobile device. You can use this to e.g. de-activate shaders 
// or grain so the code is more light-weight and runs more smoothly on mobile devices 
const isMob = /Android|webOS|iPhone|iPad|IEMobile|Opera Mini/i.test(navigator.userAgent);

function setup(){
  (isMob) ? pixelDensity(1) : pixelDensity(min(window.devicePixelRatio, 2));
  frameRate(60);

  bg = color(0,trails);
  palette = [color('#BF4E30'),color('#337AC5'),color('#dda77b'),color('#945d5e')];
  paletteIdx = 0;
  createCanvas(4/3*windowHeight, windowHeight);

  cellColour = color(255,50,10);
  attractorColour = color(0);
  ellipseMode(CENTER);

  strokeWeight(5);
  background(10);
  //galaxySetup();
  //randomSetup();
  collidingGalaxySetup();
}


function draw() {
  background(bg);

  for (var attractor of attractorList){
    attractor.attract(cellList);
    if (dynamic_attractors){
      attractor.attract(attractorList);
      attractor.move();
    }
    attractor.render();
  }

  strokeWeight(3);
  for (var cell of cellList){
    cell.move();
    cell.render();
  }
}


function randomSetup(){
  var cellColour = color(255);
  for (var i = 0; i < nC; i++){
    var newCell = new Cell(width*random(), height*random(), cellColour, 
                           3*(random()-0.5), 3*(random()-0.5));
    cellList.push(newCell);
  }

  for (i = 0; i < nA; i++){
    var attractorColour = color(0);
    var newAttractor = new Attractor(width/4 + random()*width/2, 
                                     height/4 + random()*height/2, attractorColour, 200);
    attractorList.push(newAttractor);
  }
}

function galaxySetup(){
  cellList = []
  attractorList = []
  var attractorDist = width/10;
  for (var j = 0; j < nA; j++){
    var newAttractor;
    var colour = palette[(paletteIdx++) % palette.length];
    if (nA == 1){
