function collidingGalaxySetup(){
  galaxy(width/4, height/2);
  galaxy(3*width/4, height/2);
}

function galaxy(x,y){
  var newAttractor;
  var colour = palette[(paletteIdx++) % palette.length];
  var mass = 42;
  newAttractor = new Attractor(x, y, colour, mass);
  attractorList.push(newAttractor);
  var attractorDist = width/5;
  for (var i = 0; i < 2500; i++){
    var rad = attractorDist*random(0.1,1);
    var angle = TWO_PI*random()
    var newCell = new Cell(newAttractor.p.x+rad*cos(angle), newAttractor.p.y+rad*sin(angle), colour);
    newCell.v.x = cos(angle+HALF_PI);
    newCell.v.y = sin(angle+HALF_PI);
    newCell.v.setMag(sqrt(mass/p5.Vector.dist(newAttractor.p,newCell.p)));
    cellList.push(newCell);
  }
}

function clearCanvas(){
  background(0)
  cellList = []
  attractorList = []
}

function generateColorPalette(n_colours){
  // Golden angle algorithm for getting good colour separation
  // I found that it ended up generating palettes that were quite similar fairly often so I added a 50% chance of half rotation which seems to work quite nicely
  const offset = random(360);
  var palette = []
  colorMode(HSB);
  let h = 0;
  for (let i = 0; i < n_colours; i++){
    if (random() < 0.5){
      h += 137.5
    } else {
      h += 68.75
    }
    const hue = (offset + h) % 360;
    //palette.push(color(hue, sat, brightness, 0.33));
    palette.push(color(hue, random(42,100), random(60,90), 0.33));
  }
  return palette;
}

