// === Tab: cell ===
class Cell{
  constructor(x, y, c=color(255,0,0), vx=0, vy=0){
    this.p = createVector(x,y);
    this.v = createVector(vx,vy);
    this.c = c;
  }

  move(){
    this.p.add(this.v);
  }

  accelerate(dv){
    this.v.add(dv);
  }

  render(){
    stroke(this.c);
    fill(this.c);
    point(this.p);
  }

}

// === Tab: attractor ===
class Attractor extends Cell{
  constructor(x, y, c, mass){
    super(x,y,c);
    this.mass = mass;
    this.r = 5*pow((3/4)*this.mass/PI,1/3);
  }

  attract(cellList){
    var r,dv;
    for (var cell of cellList){
      r = max(p5.Vector.dist(this.p,cell.p),15);
      dv = p5.Vector.sub(this.p,cell.p);
      dv.normalize();
      dv.setMag(this.mass/sq(r));
      cell.accelerate(dv);
    }
  }

  render(){
    stroke(this.c);
    fill(this.c);
    circle(this.p.x, this.p.y, this.r);
  }

  setMass(mass){
    this.mass = mass;
  }
}

